theorem run_preserved {S T L : Type*}
    {R : S → L → S → Prop} {R' : T → L → T → Prop} {φ : S → T}
    (h : ForwardSim R R' φ) {s t : S} {l : L} (hs : Star R s l t) :
    Star R' (φ s) l (φ t)

theorem layer_weight_ext {m n : Type} [Fintype m] [Fintype n] [DecidableEq m]
    {p q : LayerParams m n}
    (h : ∀ x : m → ℝ, layerAct p x = layerAct q x) : p.W = q.W

theorem codegenLadder_l2l3_changes_representation {n : ℕ}
    (g : (ℕ → Fin n → Float) → Float) (e : ShallowCExpr n) :
    (codegenLadder g).l2l3 e = StackCodegen.compileProg (Lattice.Geo.CExprCodegen.toStack e.val)

theorem holdsSet_mem {cs : List (GeoConstraint n)} {c : GeoConstraint n}
    (hmem : c ∈ cs) (pts : ℕ → Pt n) :
    HoldsSet cs pts → GeoConstraint.Holds c pts
